import{_ as t,o as r,c as a,a3 as n}from"./chunks/framework.BlfGB29P.js";const p=JSON.parse('{"title":"Fehlersuche","description":"","frontmatter":{},"headers":[],"relativePath":"projects/fritzbox-to-mqtt/fehlersuche.md","filePath":"projects/fritzbox-to-mqtt/fehlersuche.md","lastUpdated":1792852622000}'),o={name:"projects/fritzbox-to-mqtt/fehlersuche.md"};function i(d,e,l,s,h,c){return r(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="fehlersuche" tabindex="-1">Fehlersuche <a class="header-anchor" href="#fehlersuche" aria-label="Permalink to &quot;Fehlersuche&quot;">​</a></h1><h2 id="mqtt-meldet-not-authorized" tabindex="-1">MQTT meldet <code>Not authorized</code> <a class="header-anchor" href="#mqtt-meldet-not-authorized" aria-label="Permalink to &quot;MQTT meldet `Not authorized`&quot;">​</a></h2><p>Die App nutzt den internen MQTT-Dienst von Home Assistant. Prüfe:</p><ul><li>Mosquitto-Broker-App installiert und gestartet</li><li>MQTT-Integration eingerichtet</li><li>App neu gestartet, nachdem Mosquitto verfügbar ist</li></ul><h2 id="fritz-box-meldet-401-unauthorized" tabindex="-1">FRITZ!Box meldet <code>401 Unauthorized</code> <a class="header-anchor" href="#fritz-box-meldet-401-unauthorized" aria-label="Permalink to &quot;FRITZ!Box meldet `401 Unauthorized`&quot;">​</a></h2><p>Prüfe Benutzername, Passwort und Berechtigungen des FRITZ!Box-Benutzers. Der Benutzer muss auf die benötigten FRITZ!Box-Daten zugreifen dürfen.</p><h2 id="einzelne-werte-bleiben-unknown" tabindex="-1">Einzelne Werte bleiben <code>unknown</code> <a class="header-anchor" href="#einzelne-werte-bleiben-unknown" aria-label="Permalink to &quot;Einzelne Werte bleiben `unknown`&quot;">​</a></h2><p>Nicht jede FRITZ!Box liefert alle Werte über dieselben Schnittstellen. Die App probiert TR-064, Service-Discovery und Web-/Lua-Fallbacks. Wenn ein Wert fehlt, <code>log_value_details</code> aktivieren und die relevanten Logzeilen prüfen.</p><h2 id="port-1012" tabindex="-1">Port <code>1012</code> <a class="header-anchor" href="#port-1012" aria-label="Permalink to &quot;Port `1012`&quot;">​</a></h2><p>Port <code>1012</code> ist nur der Live-Anrufmonitor. Uploadrate, Downloadrate und Box-Status kommen nicht über Port <code>1012</code>.</p><h2 id="hacs-findet-das-projekt-nicht" tabindex="-1">HACS findet das Projekt nicht <a class="header-anchor" href="#hacs-findet-das-projekt-nicht" aria-label="Permalink to &quot;HACS findet das Projekt nicht&quot;">​</a></h2><p>Das ist erwartet. Das Projekt ist eine Supervisor-App und wird über den Home-Assistant-App-Store als Repository installiert, nicht über HACS.</p>',12)])])}const f=t(o,[["render",i]]);export{p as __pageData,f as default};
